window.__votdWeek && window.__votdWeek({"week":"2029-06-11","reading":"Doctrine and Covenants 60–63","days":[{"d":"2029-06-11","ref":"D&C 60:2","b":"D&C","c":60,"v":2,"he":"אַךְ בִּקְצָתָם לֹא חָפַצְתִּי כִּי לֹא יִפְתְּחוּ פִּיהֶם כִּי־אִם מַסְתִּירִים הַכִּשָּׁרוֹן אֲשֶׁר נָתַתִּי לָהֶם מִפְּנֵי יִרְאַת אָדָם אוֹי לָהֶם כִּי חֲרוֹן אַפִּי בֹּעֵר בָּם׃","en":"But with some I am not well pleased, for they will not open their mouths, but they hide the talent which I have given unto them, because of the fear of man. Wo unto such, for mine anger is kindled against them."},{"d":"2029-06-12","ref":"D&C 60:4","b":"D&C","c":60,"v":4,"he":"כִּי אֲנִי יְהוָה מוֹשֵׁל בַּשָּׁמַיִם מִמַּעַל וּבְצִבְאוֹת הָאָרֶץ וּבַיּוֹם אֲשֶׁר אֶעֱשֶׂה סְגֻלָּתִי יֵדְעוּ כׇל אָדָם מַה הוּא הַמּוֹרֶה עַל גְּבוּרַת אֱלֹהִים׃","en":"For I, the Lord, rule in the heavens above, and among the armies of the earth; and in the day when I shall make up my jewels, all men shall know what it is that bespeaketh the power of God."},{"d":"2029-06-13","ref":"D&C 61:31","b":"D&C","c":61,"v":31,"he":"וּבַמָּקוֹם הַהוּא יִשְׂאוּ קוֹלָם לֵאלֹהִים עַל הָעָם הַהוּא אָכֵן אֵלָיו אֲשֶׁר אַפּוֹ בֹּעֵר בְּרִשְׁעָתָם עַם קָרוֹב לְהִבָּשֵׁל לְשַׁמָּה׃","en":"And in that place they shall lift up their voices unto God against that people, yea, unto him whose anger is kindled against their wickedness, a people who are well-nigh ripened for destruction."},{"d":"2029-06-14","ref":"D&C 61:34","b":"D&C","c":61,"v":34,"he":"וּכְפִי אֲשֶׁר יַעֲשׂוּ זֹאת יְנַקּוּ בִגְדֵיהֶם וְיִהְיוּ נְקִיִּים לְפָנָי׃","en":"And inasmuch as they do this they shall rid their garments, and they shall be spotless before me."},{"d":"2029-06-15","ref":"D&C 62:1","b":"D&C","c":62,"v":1,"he":"הִנֵּה וְשִׁמְעוּ זִקְנֵי כְּנֵסִיָּתִי אָמַר יְהוָה אֱלֹהֵיכֶם גַּם יֵשׁוּעַ הַמָּשִׁיחַ מְלִיצְכֶם הַיּוֹדֵעַ חֻלְשַׁת הָאָדָם וְאֵיךְ לְסַעֵד הַמְּנֻסִּים׃","en":"Behold, and hearken, O ye elders of my church, saith the Lord your God, even Jesus Christ, your advocate, who knoweth the weakness of man and how to succor them who are tempted."},{"d":"2029-06-16","ref":"D&C 63:23","b":"D&C","c":63,"v":23,"he":"אַךְ לַשֹּׁמֵר מִצְוֹתַי אֶתֵּן סוֹדוֹת מַלְכוּתִי וְהֵם יִהְיוּ בוֹ מַעְיַן מַיִם חַיִּים נוֹבֵעַ לְחַיֵּי עוֹלָם׃","en":"But unto him that keepeth my commandments I will give the mysteries of my kingdom, and the same shall be in him a well of living water, springing up unto everlasting life."},{"d":"2029-06-17","ref":"D&C 63:47","b":"D&C","c":63,"v":47,"he":"הַנֶּאֱמָן וְהַמַּחֲזִיק יִגְבַּר עַל הָעוֹלָם׃","en":"He that is faithful and endureth shall overcome the world."}]});
